import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Pengenalan BYOK","description":"","frontmatter":{"title":"Pengenalan BYOK"},"headers":[],"relativePath":"byok/index.md","filePath":"byok/index.md"}`),a={name:`byok/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="bring-your-own-key-byok" tabindex="-1">Bring Your Own Key (BYOK) <a class="header-anchor" href="#bring-your-own-key-byok" aria-label="Permalink to “Bring Your Own Key (BYOK)”">​</a></h1><p><strong>BYOK (Bring Your Own Key)</strong> adalah mode <em>engine</em> di Mikazuki AI yang memungkinkan kamu memakai <strong>kunci API (API key) milikmu sendiri</strong> untuk menjalankan percakapan — tanpa bergantung pada kuota model <em>system</em> bawaan server. Kamu membawa model favoritmu, Mikazuki AI yang mengurus sisanya: penyusunan prompt, memori, ringkasan, dan personality karakter tetap bekerja seperti biasa.</p><blockquote><p><strong>Ringkasnya:</strong> Mode System = AI-nya Mikazuki yang bayar servernya. Mode BYOK = AI-nya kamu yang bayar providernya sendiri.</p></blockquote><hr><h2 id="kapan-memakai-byok" tabindex="-1">Kapan Memakai BYOK? <a class="header-anchor" href="#kapan-memakai-byok" aria-label="Permalink to “Kapan Memakai BYOK?”">​</a></h2><table tabindex="0"><thead><tr><th>Situasi</th><th>Rekomendasi</th></tr></thead><tbody><tr><td>Kuota/kredit model system mu terbatas atau habis</td><td>✅ BYOK</td></tr><tr><td>Ingin memakai model spesifik (mis. Gemini, Claude, DeepSeek, atau endpoint <em>OpenAI Compatible</em> sendiri)</td><td>✅ BYOK</td></tr><tr><td>Ingin full kendali atas kreativitas (temperature, <code>top_p</code>, <code>max_tokens</code>, <code>context window</code>)</td><td>✅ BYOK</td></tr><tr><td>Pengguna baru yang belum punya API key manapun</td><td>❌ Pakai Mode System dulu</td></tr><tr><td>Ingin percakapan tanpa memikirkan apapun</td><td>❌ Mode System</td></tr></tbody></table><hr><h2 id="provider-yang-didukung" tabindex="-1">Provider yang Didukung <a class="header-anchor" href="#provider-yang-didukung" aria-label="Permalink to “Provider yang Didukung”">​</a></h2><p>Mikazuki AI mendukung banyak provider langsung dari Go worker-nya:</p><p><strong>Provider native (implemented di worker):</strong></p><ul><li>Google Gemini</li><li>Anthropic Claude</li><li>DeepSeek</li><li>Mistral AI</li><li>OpenRouter</li><li>Z.AI (Zhipu)</li><li>Groq</li><li>Featherless</li><li>NanoGPT</li><li>Venus</li><li>Chutes</li></ul><p><strong>Provider berbasis endpoint publik (tanpa API key):</strong></p><ul><li>ArliAI</li><li>Mancer</li><li>AI Horde</li><li>NovelAI</li></ul><p><strong>Provider berbasis endpoint kustom:</strong></p><ul><li>OpenAI Compatible — isi <em>Base URL</em> sendiri (cocok untuk server Lokal seperti Ollama / llama.cpp yang memakai layout API OpenAI, atau endpoint pihak ketiga apa pun)</li></ul><hr><h2 id="cara-mengaktifkan" tabindex="-1">Cara Mengaktifkan <a class="header-anchor" href="#cara-mengaktifkan" aria-label="Permalink to “Cara Mengaktifkan”">​</a></h2><p>Aktivasi BYOK cukup cepat: kamu hanya perlu satu API key dari provider pilihanmu, lalu mengubah mode engine di halaman pengaturan. Panduan lengkap langkah demi langkah — termasuk cara mengisi <em>Base URL</em> untuk endpoint kustom dan catatan keamanan penyimpanan key — ada di halaman <a href="./instalasi.html">Instalasi &amp; Aktivasi</a>.</p><blockquote><p>⚠️ <strong>Catatan Privasi:</strong> API key-mu <strong>disimpan lokal di perangkatmu</strong> (IndexedDB + localStorage), bukan di database server. Ia hanya melewati server sebagai bagian payload request saat mengobrol. Jangan bagikan key-mu ke siapa pun.</p></blockquote><p>Setelah BYOK aktif, panel <strong>&quot;Opsi Lanjutan&quot;</strong> memberimu kendali atas parameter seperti <code>max_tokens</code>, <code>context_window</code>, <code>temperature</code>, dan lainnya. Penjelasan tiap parameter — termasuk tabel parameter kreativitas dan Advanced Payload — dibahas di halaman <a href="./parameter-dasar.html">Parameter Dasar</a>.</p><hr><h2 id="apa-saja-yang-tetap-sama-di-mode-byok" tabindex="-1">Apa Saja yang Tetap Sama di Mode BYOK? <a class="header-anchor" href="#apa-saja-yang-tetap-sama-di-mode-byok" aria-label="Permalink to “Apa Saja yang Tetap Sama di Mode BYOK?”">​</a></h2><p>BYOK hanya mengganti &quot;otak&quot; yang memproses jawaban. Seluruh fitur Mikazuki tetap berlaku:</p><ul><li>✅ <strong>Memori Chat &amp; Global Memories (VIP)</strong> — lengkap.</li><li>✅ <strong>Ringkasan (Summary) / Re-Summary</strong> — tetap berjalan.</li><li>✅ <strong>Persona, System Notes, gaya bahasa karakter</strong> — identik.</li><li>✅ <strong>Bond, Memories, dan Hapus Lanjutan (Dynamic Delete)</strong> — tetap jalan.</li><li>✅ Validasi &amp; streaming layout (mengetik animasi) — sama.</li></ul><hr><h2 id="faq-singkat" tabindex="-1">FAQ singkat <a class="header-anchor" href="#faq-singkat" aria-label="Permalink to “FAQ singkat”">​</a></h2><details class="details custom-block"><summary>Apakah chat BYOK masih masuk ke memori ringkasan yang sama?</summary><p>Ya. Overflow riwayat lama tetap dikemas menjadi <em>Recap</em> dan <em>Memori Chat</em> di perangkatmu, sama seperti Mode System.</p></details><details class="details custom-block"><summary>Apakah credits / kuota VIP saya dipakai di BYOK?</summary><p>Tidak. Request BYOK berjalan dengan kredensialmu sendiri, sehingga kuota sistem tidak terbebani. Namun fitur <strong>Global Memori (VIP)</strong> tetap mengikuti status akunmu.</p></details><details class="details custom-block"><summary>Key saya terekam di log?</summary><p>Tidak. API key tidak pernah ditulis ke log server — ia hanya melewati payload request saat percakapan berlangsung, tidak disimpan di database.</p></details><details class="details custom-block"><summary>Hum, model saya tidak tampil di daftar?</summary><p>Periksa API key dan <em>Base URL</em> (untuk OpenAI Compatible), lalu tekan tombol 🔍 lagi. Jika provider menolak endpoint resmi atau memakai endpoint khusus, coba isi nama model secara manual pada kolom Model.</p></details><hr><h2 id="selanjutnya" tabindex="-1">Selanjutnya <a class="header-anchor" href="#selanjutnya" aria-label="Permalink to “Selanjutnya”">​</a></h2><ul><li>Siapkan API key dan aktifkan BYOK lewat panduan <a href="./instalasi.html">Instalasi &amp; Aktivasi</a>.</li><li>Kenali parameter di panel Opsi Lanjutan lewat halaman <a href="./parameter-dasar.html">Parameter Dasar</a>.</li><li>Pakai <strong>preset Context Window</strong> <code>1M</code> untuk percakapan super panjang dengan karakter yang konsisten memori — detail di <a href="./parameter-dasar.html">Parameter Dasar</a>.</li><li>Kelola memori karakter bersama fitur <strong>Hapus Lanjutan (Dynamic Delete)</strong> di dalam aplikasi.</li></ul>`,33)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};